class ConfigRemoteLbralign(GenericRtg):
    """Command for aligning LBR with RTG components."""

    def __init__(self, connection, target="", prompt=None, newline_chars=None, runner=None):
        """
        Config remote lbralign.

        :param connection: moler connection to device, terminal when command is executed.
        :param
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ConfigRemoteLbralign, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.target = target
        self.devices = {}
        self.current_ret["aligned_sectors"] = set()
        self.error = ""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"config remote lbralign {self.target}"
        return cmd

    # Example line: ERROR: Test in progress, cannot proceed
    _re_error_parsing_need = re.compile(r"output:\s*$")

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_successfully_aligned(line)
            except ParsingDone:
                pass

        return super(ConfigRemoteLbralign, self).on_new_line(line, is_full_line)

    # Example line:
    _re_empty_line = re.compile(r"^\s*$")
    # Example line: 10: 36:56 | c11 | Applying raw for [ctrl_11][sector_11] eNB=bcu3 HW=FZP
    _re_sector_align_started = re.compile(r"\|\s*(?P<KEY>\w+)\s*\|.*\[\w*\]\[(?P<SECTOR>.*)\]")
    # Example line: 10:37:05|c11|RMOD-1 is UP
    _re_device_align_successful = re.compile(r"\|\s*(?P<KEY>\w+)\s*\|")

    def _parse_successfully_aligned(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(ConfigRemoteLbralign._re_empty_line, line):
            raise ParsingDone
        else:
            align_started = self._regex_helper.search(ConfigRemoteLbralign._re_sector_align_started, line)
            align_successful = self._regex_helper.search(ConfigRemoteLbralign._re_device_align_successful, line)
            if align_started:
                self.devices[align_started.group("KEY")] = align_started.group("SECTOR")
            if align_successful:
                key = align_successful.group("KEY")
                if key in self.devices.keys():
                    self.current_ret["aligned_sectors"].add(self.devices[key])

    # Example line: ERROR: Test in progress, cannot proceed
    _re_error = re.compile(r"ERROR:\s*(?P<ERROR>.*)$")
    # Example line: Invalid target specs: wrong
    _re_invalid_target = re.compile(r"Invalid target specs:\s*(?P<TARGET>.*)$")
    # Example line: No FLEXI-FZM CTRLs to perform raw config
    _re_no_lbr_error = re.compile(r"No\b.*\bCTRLs")

    def _parse_error(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        # wrong target specified
        if self._regex_helper.search(self._re_invalid_target, line):
            self.error = f"Invalid Target: {self._regex_helper.group('TARGET')}\n"
            self.set_exception(CommandFailure(self, f"Invalid Target: {self._regex_helper.group('TARGET')}"))
            raise ParsingDone
        # found error
        if self._regex_helper.search(ConfigRemoteLbralign._re_error, line):
            self.error = f"{self._regex_helper.group('ERROR')}\n"
            self.set_exception(CommandFailure(self, f"ERROR: {self.error}"))
            raise ParsingDone
        if self._regex_helper.search(self._re_no_lbr_error, line):
            self.set_exception(CommandFailure(self, "No LBR in your configuration."))
            raise ParsingDone


